window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-35801\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώλεο</h1><div class=\"entry-meta\"><span>DGP · ordem 5483 na letra π · nº geral 35801</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. impf. jôn. poét. de πωλέομαι.</p></section></article>\n<article id=\"entry-dgp-35802\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 5484 na letra π · nº geral 35802</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πωλήσομαι, aor. e perf. desus.) vir frequentemente; frequentar: π. εἰς ἀγορήν hom. ir à assembléia.</p></section></article>\n<article id=\"entry-dgp-35803\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλέσκετο</h1><div class=\"entry-meta\"><span>DGP · ordem 5485 na letra π · nº geral 35803</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de πωλέομαι.</p></section></article>\n<article id=\"entry-dgp-35804\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλεῦμαι, πωλεύμην</h1><div class=\"entry-meta\"><span>DGP · ordem 5486 na letra π · nº geral 35804</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pres. e impf. jôn. poét. de πωλέομαι.</p></section></article>\n<article id=\"entry-dgp-35805\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλεύτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5487 na letra π · nº geral 35805</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">domador, adestrador de potros ou de animais novos. 〈πωλεύω〉</p></section></article>\n<article id=\"entry-dgp-35806\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5488 na letra π · nº geral 35806</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hábil em adestrar potros. 〈πωλεύω〉</p></section></article>\n<article id=\"entry-dgp-35807\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 5489 na letra π · nº geral 35807</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adestrar potros ou animais novos. 〈πῶλος〉</p></section></article>\n<article id=\"entry-dgp-35808\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5490 na letra π · nº geral 35808</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπώλουν, fut. πωλήσω, aor. ἐπώλησα, perf. desus.) 1 vender algo, ac., a alguém, dat. ou πρός e ac., a preço de, gen. ou πρός e ac.: τὴν ὥραν ἀργυρίου πωλεῖν τῷ βουλομένῳ xen. vender ao interessado a juventude a preço de prata, τῶν πόνων πωλοῦσιν ἡμῖν πάντα τἀγάθ’ οἱ θεοί xen. os deuses nos vendem todos os bens ao custo de sofrimentos 2 vender; entregar a preço de ouro, algo ou alguém 3 arrecadar; executar (imposto, tributo) ♦ méd. 4 vender-se; prostituir-se.</p></section></article>\n<article id=\"entry-dgp-35809\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώλησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5491 na letra π · nº geral 35809</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">venda. 〈πωλέω〉</p></section></article>\n<article id=\"entry-dgp-35810\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5492 na letra π · nº geral 35810</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 em Atenas, magistrado encarregado de cobrar ou executar as taxas públicas 2 em Epidamno, comissário enviado anualmente a países vizinhos para acertar operações comerciais. 〈πωλέω〉</p></section></article>\n<article id=\"entry-dgp-35811\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5493 na letra π · nº geral 35811</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de potro: πωλικὴ ἀπήνη sóf. carro puxado por potros, π. διώγματα eur. perseguição em carro puxado por potros 2 de moça. 〈πῶλος〉</p></section></article>\n<article id=\"entry-dgp-35812\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5494 na letra π · nº geral 35812</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">potro pequeno. 〈πῶλος〉</p></section></article>\n<article id=\"entry-dgp-35813\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλοδαμνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5495 na letra π · nº geral 35813</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 domar potros 2 adestrar potros 3 adestrar; domesticar; treinar 4 formar (pessoa). 〈πωλοδάμνης〉</p></section></article>\n<article id=\"entry-dgp-35814\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλοδάμνης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5496 na letra π · nº geral 35814</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">domador, adestrador de potros. 〈πῶλος, δάμνημι〉</p></section></article>\n<article id=\"entry-dgp-35815\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλοδαμνική, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5497 na letra π · nº geral 35815</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arte de domar ou adestrar potros. 〈πωλοδάμνης〉</p></section></article>\n<article id=\"entry-dgp-35816\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶλος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5498 na letra π · nº geral 35816</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 potro, potra 2 cavalo 3 animal novo; filhote (de elefante, de camelo) 4 moça, moço 5 moeda coríntia com a estampa do cavalo Pégaso.</p></section></article>\n<article id=\"entry-dgp-35817\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλοτροφική, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5499 na letra π · nº geral 35817</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arte de criar potros. 〈πωλοτρόφος〉</p></section></article>\n<article id=\"entry-dgp-35818\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωλοτρόφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5500 na letra π · nº geral 35818</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que alimenta potros 2 que cria filhotes 3 domador; adestrador. 〈πῶλος, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-35819\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶμα1, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5501 na letra π · nº geral 35819</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tampa de vaso ou de tonel 2 tampa de aljava 3 tampa de baú ou de alçapão 4 pedra que bloqueia a entrada de uma caverna.</p></section></article>\n<article id=\"entry-dgp-35820\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶμα2, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5502 na letra π · nº geral 35820</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 o que se bebe; bebida; poção 2 água potável.</p></section></article>\n<article id=\"entry-dgp-35821\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 5503 na letra π · nº geral 35821</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fechar com uma tampa; tampar; tapar; cobrir. 〈πῶμα1〉</p></section></article>\n<article id=\"entry-dgp-35822\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώμαλα</h1><div class=\"entry-meta\"><span>DGP · ordem 5504 na letra π · nº geral 35822</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo algum; de nenhuma maneira; absolutamente não. 〈πω, μάλα〉</p></section></article>\n<article id=\"entry-dgp-35823\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώποτε</h1><div class=\"entry-meta\"><span>DGP · ordem 5505 na letra π · nº geral 35823</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 às vezes; alguma vez por acaso: ἤδη πώποτέ του ἤκουσας αὐτῶν λόγον διδόντος οὐ κατα­γέλαστον; plat. já ouviste alguma vez um deles proferindo uma fala que não fosse ridícula? εἶ τις πώποτε xen. se um dia alguém 2 com ou sem neg., πώποτε ou οὐ πώποτε, μὴ πώποτε, οὐδεπώποτε, μηδεπώποτε nunca; jamais: οἱ πώποτε γενόμενοι isócr. aqueles que nunca existiram, οἱ πώποτε ἁψάμενοι λόγων plat. aqueles que nunca empregaram discursos 3 de qualquer modo; de qualquer maneira. 〈πώ, ποτέ〉</p></section></article>\n<article id=\"entry-dgp-35824\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώρινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5506 na letra π · nº geral 35824</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de tufo: π. λίθος her. pedra da espécie do tufo. 〈πῶρος〉</p></section></article>\n<article id=\"entry-dgp-35825\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5507 na letra π · nº geral 35825</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tufo, espécie de pedra calcária muito porosa 2 concreção de estalactite 3 mármore semelhante ao de Paros, mas menos compacto 4 Medic. concreção gotosa 5 Medic. concreção pedrosa na urina 6 calosidade.</p></section></article>\n<article id=\"entry-dgp-35826\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5508 na letra π · nº geral 35826</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tornar caloso; endurecer 2 solidificar (osso fraturado); formar calo 3 endurecer; tornar insensível ♦ pas. 4 Medic. (cálculo vesicular) petrificar-se 5 bíbl. (coração) endurecer-se; tornar-se insensível 6 bíbl. ficar cego. 〈πῶρος〉</p></section></article>\n<article id=\"entry-dgp-35827\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώρωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5509 na letra π · nº geral 35827</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. soldadura de um osso por meio de um calo 2 endurecimento 3 obtusidade; insensibilidade. 〈πωρόω〉</p></section></article>\n<article id=\"entry-dgp-35828\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 5510 na letra π · nº geral 35828</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. interrogativo 1 como? de que maneira? com partíc. πῶς ἄν, ép. πῶς κε (κεν) 2 como? i.e., por que? πῶς δέ; mas como? πῶς δή; πῶς δῆτα; como então? como assim? 3 πῶς γάρ; καὶ πῶς; expr. de indignação ou de impossibilidade, como então? como isso? πῶς οὔ; ou πῶς οὐχί; como não? como isso não seria assim? 4 expr. de espanto, como, i.e., o quê? πῶς νῦν; e agora, como fica a situação? i.e., o que pensas agora disso? 5 como?, i.e., por quanto? exclamativo 6 como! quão! 1 πῶς δοκεῖς; plat. como te parece? πῶς κ’ ἔοι; hom. como seria isso? que ar isso teria? πῶς ἄν θάνοιμι; sóf. como poderia eu ser morto? i.e., possa eu morrer! μένω ἀκοῦσαι πῶς ἀγὼν κριθήσεται ésql. fico para saber como a causa será decidida, πῶς κέν μοι ὑποσχόμενος τελέσειας μῦθον ἐμόν; hom. como poderias comprometer-te a realizar o meu pedido? 2 πῶς ταῦτ’ ἔλεξας; ésql. como disseste isso? πῶς οὖν οὐ καὶ σὺ παιδεύεις; xen. como tu também não ensinas? πῶς δὲ σὺ νῦν μένονας; hom. mas como tu pôdes ousar? πῶς τί τοῦτο λέγεις; plat. como dizes isso e por quê? 3 πῶς γάρ τοι δώσουσι γέρας Ἀχαιοί; hom. como então os aqueus vão te presentear? πῶς γὰρ κάτοιδα; sóf. como poderia eu te conhecer? κἀγὼ μὲν οὐκ ἔδρασα, οὐδ’ αὖ σύ· πῶς γάρ; sóf. e não fui eu quem fez, e muito menos tu; pois, como seria possível? καὶ πῶς σιωπῶ; eur. e como me calarei? i.e., não posso calar-me, πῶς οὐ δεινὰ εἴργασθε; tuc. como não cometestes uma ação medonha? i.e., como podeis pretender que não cometestes? πῶς οὐκ αδικεῖς; dem. como não estás errado? i.e., é claro que estás errado 4 πῶς εἶπας; ésql. como disseste? i.e., o que é que disseste? πῶς λέγεις; sóf., πῶς φῇς; ésql. como dizes? o que estás dizendo? 5 τὰ ἄλφιθ’ ὑμῖν πῶς ἐπώλουν; ar. como, i.e., por quanto vos vendiam o trigo? Μεγαροῖ πῶς ὁ σῖτος ὤνιος; ar. por quanto a farinha pode ser comprada em Mégara? 6 πῶς δυσκόλως οἱ τὰ χρήματα ἔχοντες εἰς τὴν βασιλείαν τοῦ θεοῦ εἰσελεύσονται n.t. quão dificilmente os que têm riquezas entrarão no reino de Deus</p></section></article>\n<article id=\"entry-dgp-35829\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώς,</h1><div class=\"entry-meta\"><span>DGP · ordem 5511 na letra π · nº geral 35829</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">encl. πως adv. 1 de algum modo; de qualquer maneira: εἴ πως át., αἴ πως ép. se de alguma maneira, οὔ πως ou οὔπως, μή πως ou μήπως de maneira alguma 2 mais ou menos; quase; aproximadamente: τοιαῦτα… πώς aproximadamente de tal modo, ὦδέ πως xen. mais ou menos assim, ἄλλως πως xen. de alguma outra forma, μόγις πως plat. com alguma dificuldade, πράσσοντές πως ταῦτα tuc. fazendo mais ou menos isso.</p></section></article>\n<article id=\"entry-dgp-35830\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πωτάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 5512 na letra π · nº geral 35830</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πωτήσομαι, aor. ἐπωτήθην) voar. 〈ποτάομαι〉</p></section></article>\n<article id=\"entry-dgp-35831\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πώτημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5513 na letra π · nº geral 35831</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vôo; impulso. 〈πωτάομαι〉</p></section></article>\n<article id=\"entry-dgp-35832\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῶϋ, πώεος,</h1><div class=\"entry-meta\"><span>DGP · ordem 5514 na letra π · nº geral 35832</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. πώεα (τό) rebanho de carneiros ou de ovelhas.</p></section></article>\n<article id=\"entry-dgp-35833\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ρ, ῥ (ῥῶ) (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1 na letra ρ · nº geral 35833</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rô, 17ª letra do alfabeto grego ♦ num. 2 ρʹ = 100 ou 100° 3 ͵ρ = 100.000 ou 100.000°.</p></section></article>\n<article id=\"entry-dgp-35834\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥά</h1><div class=\"entry-meta\"><span>DGP · ordem 2 na letra ρ · nº geral 35834</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. encl., poét. = ἄρα.</p></section></article>\n<article id=\"entry-dgp-35835\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3 na letra ρ · nº geral 35835</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bater com vara (cereais, trigo, lã), ac.; varejar uma árvore 2 vergastar alguém. 〈ῥάβδος〉</p></section></article>\n<article id=\"entry-dgp-35836\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 4 na letra ρ · nº geral 35836</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequena vara; pequeno galho; pequena haste 2 pequeno bastão, partic. o caduceu de Hermes 3 pequena haste de ferro (para espalhar verniz sobre quadros) 4 pl. barbas (na boca de certos peixes). 〈ῥάβδος〉</p></section></article>\n<article id=\"entry-dgp-35837\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδομαχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5 na letra ρ · nº geral 35837</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combate travado por meio de estilete, bastão ou vara. 〈ῥάβδος, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-35838\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδονομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6 na letra ρ · nº geral 35838</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser juiz de combate; exercer a função de árbitro (empunhando uma vara). 〈ῥάβδος, νόμος〉</p></section></article>\n<article id=\"entry-dgp-35839\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδονόμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7 na letra ρ · nº geral 35839</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lictor, em Roma. 〈ῥάβδος, νέμω〉</p></section></article>\n<article id=\"entry-dgp-35840\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάβδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 8 na letra ρ · nº geral 35840</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vara; ramo; sarmento 2 vara (de bater) 3 caduceu de Hermes 4 vara mágica (de Circe) 5 vara de pescar 6 bastão ou vara de pastor 7 varinha untada de visco 8 bastão de comando; cetro 9 batuta dos rapsodos 10 haste de lança 11 linha; listra; veio (na pedra); estria (na pele) 12 veio de mineral 13 rebento de vegetal 14 ponto no cozimento.</p></section></article>\n<article id=\"entry-dgp-35841\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδουχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 9 na letra ρ · nº geral 35841</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 levar o bastão ou feixes de varas como insígnia ♦ pas. 2 ser precedido de lictores, em Roma. 〈ῥαβδοῦχος〉</p></section></article>\n<article id=\"entry-dgp-35842\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδουχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 10 na letra ρ · nº geral 35842</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 função de levar o feixe de varas, i.e., função de lictor, em Roma 2 tropa ou escolta de lictores levando bastões. 〈ῥαβδοῦχος〉</p></section></article>\n<article id=\"entry-dgp-35843\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδοῦχος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 11 na letra ρ · nº geral 35843</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 árbitro de concursos, em Olím­pia 2 porta-bastão; meirinho; porteiro de certos magistrados 3 lictor, em Roma 4 fem. pl., mulheres acompanhantes da mãe de Agátocles, em Siracusa. 〈ῥάβδος, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-35844\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαβδωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 12 na letra ρ · nº geral 35844</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 raiado; canelado; estriado 2 feito de varas. 〈ῥάβδος〉</p></section></article>\n<article id=\"entry-dgp-35845\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾶγα</h1><div class=\"entry-meta\"><span>DGP · ordem 13 na letra ρ · nº geral 35845</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. sing. de ῥάξ.</p></section></article>\n<article id=\"entry-dgp-35846\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαγδαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 14 na letra ρ · nº geral 35846</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 impetuoso; furioso; violento (fenômeno atmosférico) 2 raivoso; encolerizado (pessoa) ♦ τό ῥαγδαῖον 3 violência; furor. 〈ῥάγδην〉</p></section></article>\n<article id=\"entry-dgp-35847\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάγδην</h1><div class=\"entry-meta\"><span>DGP · ordem 15 na letra ρ · nº geral 35847</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. bruscamente; violentamente; impetuosamente. 〈ῥαγή〉</p></section></article>\n<article id=\"entry-dgp-35848\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαγείς, εῖα, έν</h1><div class=\"entry-meta\"><span>DGP · ordem 16 na letra ρ · nº geral 35848</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. de ῥήγνυμι.</p></section></article>\n<article id=\"entry-dgp-35849\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 17 na letra ρ · nº geral 35849</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fenda; rachadura. 〈ῥήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-35850\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαδαλός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 18 na letra ρ · nº geral 35850</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">móvel; fácil de mover. Ῥαδάμανθυς, υος (ὁ) Radamanto, herói cretense, um dos juízes do Hades.</p></section></article>\n<article id=\"entry-dgp-35851\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαδινάκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 19 na letra ρ · nº geral 35851</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">petróleo. [persa]</p></section></article>\n<article id=\"entry-dgp-35852\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαδινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 20 na letra ρ · nº geral 35852</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 leve; flexível (chicote, planta) 2 tenro; delicado (membros) 3 ágil; rápido; ligeiro; veloz (partes do corpo): ῥαδιναῖς χερσί teóg. com mãos ágeis, ποσσὶν ὑπὸ ῥαδινοῖσιν hes. sob pés ligeiros, ἀπ’ ὄσσων ῥαδινῶν ésql. de olhos ágeis 4 alto, delgado (colunas).</p></section></article>\n<article id=\"entry-dgp-35853\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾴδιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 21 na letra ρ · nº geral 35853</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον (comp. ῥᾴων, ép. ῥηΐτερος; superl. ῥᾷστος, ép. ῥηΐτατος) 1 fácil; cômodo; livre; desembaraçado; frouxo: ῥᾴδιον πολεμίζειν hom. fácil de combater, ῥᾴδιον δαμήναι hom. fácil de subjugar, ῥᾴδιόν ἐστι é fácil, inf.; comp. ῥᾴων γενέσθαι ou εἶναι sentir-se ou estar melhor 2 de humor fácil; acessível; complacente; obsequioso 3 leviano; sem escrúpulo 4 supérfluo; frívolo.</p></section></article>\n<article id=\"entry-dgp-35854\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳδιουργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 22 na letra ρ · nº geral 35854</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 executar com facilidade, com ligeireza algo, ac. 2 agir negligentemente, levianamente 3 ser descuidado, indolente, negligente 4 comportar-se mal; não ter escrúpulos; agir de modo desleal. 〈ῥᾳδιουργός〉</p></section></article>\n<article id=\"entry-dgp-35855\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳδιούργημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 23 na letra ρ · nº geral 35855</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação irrefletida; ação leviana; falha; erro 2 falsificação; invenção. 〈ῥᾳδιουργέω〉</p></section></article>\n<article id=\"entry-dgp-35856\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳδιουργία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 24 na letra ρ · nº geral 35856</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 facilidade de fazer algo 2 indolência; preguiça 3 negligência; falta de cuidado 4 falta de escrúpulos 5 fraude; engano. 〈ῥᾳδιουργός〉</p></section></article>\n<article id=\"entry-dgp-35857\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαδιουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 25 na letra ρ · nº geral 35857</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que age com ligeireza; que faz as coisas sem cuidado 2 inescrupuloso; sem consciência; perverso; mau (pessoa) 3 impostor 4 falsário; contraventor 5 impuro; mal feito (sacrifício). 〈ῥᾴδιος, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-35858\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳδίως</h1><div class=\"entry-meta\"><span>DGP · ordem 26 na letra ρ · nº geral 35858</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. (comp. ῥᾷον; superl. ῥᾷστα) 1 facilmente; sem dificuldade 2 sem cuidado; levianamente; sem reflexão.</p></section></article>\n<article id=\"entry-dgp-35859\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαθάμιγξ, ιγγος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 27 na letra ρ · nº geral 35859</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gota d’água 2 grão de poeira; poeira. 〈ῥαίνω〉</p></section></article>\n<article id=\"entry-dgp-35860\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳθυμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 28 na letra ρ · nº geral 35860</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ῥαθυμέω-ῶ 1 ter relaxamento de ânimo; entregar-se à preguiça; ser indolente 2 ser descuidado; ser negligente em algo, ἐπί e dat. ou περί e gen. ou ac. 〈ῥᾴθυμος〉</p></section></article>\n<article id=\"entry-dgp-35861\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳθυμία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 29 na letra ρ · nº geral 35861</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 relaxamento; repouso; recreação; divertimento 2 enfraquecimento de ânimo, de vontade, de atividade; indolência 3 fraqueza de caráter, de disposição 4 ausência de cuidados; desleixo; incúria. 〈ῥᾴθυμος〉</p></section></article>\n<article id=\"entry-dgp-35862\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾴθυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 30 na letra ρ · nº geral 35862</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que toma as coisas com indiferença; indiferente; inerte 2 de ânimo fraco; indolente 3 descuidado; negligente 4 sem dificuldade; fácil; cômodo. 〈ῥᾴθυμος〉</p></section></article>\n<article id=\"entry-dgp-35863\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαθύμως</h1><div class=\"entry-meta\"><span>DGP · ordem 31 na letra ρ · nº geral 35863</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com ânimo relaxado; com calma; tranquilamente; pacientemente 2 com indolência; tibiamente 3 negligentemente.</p></section></article>\n<article id=\"entry-dgp-35864\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαΐζω</h1><div class=\"entry-meta\"><span>DGP · ordem 32 na letra ρ · nº geral 35864</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (doença) tornar-se menos grave; perder a força; atenuar-se 2 (doente) recuperar as forças; melhorar; estar melhor 3 repousar 4 aliviar; tornar mais leve (um mal). 〈ῥᾴων〉</p></section></article>\n<article id=\"entry-dgp-35865\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαίῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 33 na letra ρ · nº geral 35865</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. subj. pres. at. de ῥαίω.</p></section></article>\n<article id=\"entry-dgp-35866\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 34 na letra ρ · nº geral 35866</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔρραιον, fut. ῥανῶ, aor. ἔρρανα, perf. desus., m.-q.-perf. ἔρραμμαι; pas. fut. ῥανθήσομαι, aor. ἐρράνθην) 1 aspergir; regar; inundar; encharcar algo ou alguém, ac., de algo, dat. 2 aspergir; salpicar; borrifar (libação) 3 cobrir algo ou alguém, ac., com ou de algo (canto, elogio), dat. 4 espalhar ♦ pas. 5 estar inundado, banhado; cobrir-se de (coisas secas).</p></section></article>\n<article id=\"entry-dgp-35867\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαισέμεναι</h1><div class=\"entry-meta\"><span>DGP · ordem 35 na letra ρ · nº geral 35867</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. fut. at. ép. de ῥαίω.</p></section></article>\n<article id=\"entry-dgp-35868\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαιστήρ, ῆρος (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 36 na letra ρ · nº geral 35868</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 martelo 2 flagelo devastador. 〈ῥαίω〉</p></section></article>\n<article id=\"entry-dgp-35869\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάϊστος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 37 na letra ρ · nº geral 35869</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">super. poét. de ῥᾴδιος.</p></section></article>\n<article id=\"entry-dgp-35870\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαίω</h1><div class=\"entry-meta\"><span>DGP · ordem 38 na letra ρ · nº geral 35870</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔρραιον, fut. ῥαίσω, aor. ἔραισσα, perf. desus.; aor. pas. ἐρραίσθην) 1 reduzir a pedaços; quebrar; destroçar 2 fazer naufragar (navio): Ποσειδάων εὐεργέα νῆ’ ἐπὶ πόντῳ ῥαίσε hom. Posidão destroçara no mar a bem-construída nau 3 abater em naufrágio; destruir alguém: εἰ δ’ αὖ τις ῥαίῃσι θεῶν μ’ ἐνὶ οἴνοπι πόντῳ hom. se um deus me fizer naufragar no mar vinoso 4 alquebrar 5 destruir; aniquilar 6 maltratar; ultrajar ♦ pas. 7 afundar com a nau; naufragar 8 despedaçar-se; quebrar: ἀμφὶ δὲ καυλὸν φάσγανον ἐρραίσθη hom. a espada, porém, se quebrou na empunhadeira 9 ser alquebrado pelo sofrimento 10 ser maltratado, ofendido.</p></section></article>\n<article id=\"entry-dgp-35871\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥακά</h1><div class=\"entry-meta\"><span>DGP · ordem 39 na letra ρ · nº geral 35871</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. tolo; burro, termo ofensivo. [hebr.]</p></section></article>\n<article id=\"entry-dgp-35872\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 40 na letra ρ · nº geral 35872</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trapo; farrapo; andrajos; vestes sujas, rasgadas. 〈ῥάκος〉</p></section></article>\n<article id=\"entry-dgp-35873\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάκος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 41 na letra ρ · nº geral 35873</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trapos; andrajos; pedaços de tecido; remendos; vestes rasgadas; frangalhos: δὸς δὲ ῥάκος ἀμφιβαλείσθαι hom. dá-me uns andrajos para cobrir-(me) 2 pedaços: δαιφονὸς αἰετός, λάβρως διαρταμήσει σώματος μέγα ῥάκος ésql. a fulva águia irá ferozmente dilacerar teu corpo em muitos farrapos 3 restos; fragmentos; ruínas (de casa, da vida) 4 rugas; franzidos: τοῦ προσώπου τὰ ῥάκη ar. as rugas do rosto 5 venda; gaze.</p></section></article>\n<article id=\"entry-dgp-35874\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥακόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 42 na letra ρ · nº geral 35874</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer em frangalhos 2 fazer murchar; enfraquecer; debilitar ♦ pas. 3 cair aos pedaços 4 enrugar-se; franzir-se 5 dispersar-se por todos os lados. 〈ῥάκος〉</p></section></article>\n<article id=\"entry-dgp-35875\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάμφος, εος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 43 na letra ρ · nº geral 35875</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bico adunco das aves de rapina; bico.</p></section></article>\n<article id=\"entry-dgp-35876\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥανίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 44 na letra ρ · nº geral 35876</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gota d’água; gota de chuva 2 gota (de sangue) 3 gota de esperma 4 pequena mancha; nódoa; pequeno ponto. 〈ῥαίνω〉</p></section></article>\n<article id=\"entry-dgp-35877\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαντήριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 45 na letra ρ · nº geral 35877</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">banhado; molhado. 〈ῥαντήρ〉</p></section></article>\n<article id=\"entry-dgp-35878\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαντίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 46 na letra ρ · nº geral 35878</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 tard. aspergir 2 bíbl. purificar. 〈ῥαντός〉</p></section></article>\n<article id=\"entry-dgp-35879\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαντισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 47 na letra ρ · nº geral 35879</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aspersão. 〈ῥαντίζω〉</p></section></article>\n<article id=\"entry-dgp-35880\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαντός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 48 na letra ρ · nº geral 35880</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. sujo; manchado. 〈ῥαίνω〉</p></section></article>\n<article id=\"entry-dgp-35881\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάξ, ῥαγός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 49 na letra ρ · nº geral 35881</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 grão de uva; cacho de uva; baga 2 bago de outras frutas 3 pequena aranha venenosa 4 pl. pontas dos dedos.</p></section></article>\n<article id=\"entry-dgp-35882\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾷον</h1><div class=\"entry-meta\"><span>DGP · ordem 50 na letra ρ · nº geral 35882</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. n. de ῥᾴδιος e de ῥᾳδίως.</p></section></article>\n<article id=\"entry-dgp-35883\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 51 na letra ρ · nº geral 35883</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐρράπιζον, fut. ῥαπίσω, aor. ἐρράπισα, perf. desus.; aor. pas. ἐρραπίσθην, perf. pas. ῥεράπισμαι) 1 bater com vara, bastão, chibata, bengala em, ac. 2 bater no rosto; esbofetear ♦ pas. 3 ser ferido; ser espancado.</p></section></article>\n<article id=\"entry-dgp-35884\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάπισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 52 na letra ρ · nº geral 35884</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. 1 golpe de vara 2 bofetada. 〈ῥαπίζω〉</p></section></article>\n<article id=\"entry-dgp-35885\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 53 na letra ρ · nº geral 35885</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cosido; costurado 2 remendado (túnica) 3 feito de peles costuradas: πλοῖα ῥαπτά estr. embarcações feitas de peles cosidas juntas 4 pontilhado 5 pl. ligados; encadeados; contínuos (versos), ref. à poesia épica ♦ τὸ ῥαπτόν 6 tapete bordado. 〈ῥάπτω〉</p></section></article>\n<article id=\"entry-dgp-35886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 54 na letra ρ · nº geral 35886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ῥάψω, aor. ἔρραψα, perf. desus.; aor.2 pas. ἐρράσθην, perf. pas. ἔρραμμαι) 1 ligar costurando; coser junto; coser (peles) 2 tramar; urdir; maquinar algo, ac., contra alguém, dat. ou εἰς, ἐπί e ac.: οὐκ ὄφελον Τρώεσσι κοτεσσαμένη κακὰ ῥάψαι hom. não é justo que eu [Hera], irritada, trame desgraças para os troianos?</p></section></article>\n<article id=\"entry-dgp-35887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάσσατε</h1><div class=\"entry-meta\"><span>DGP · ordem 55 na letra ρ · nº geral 35887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª pl. imper. aor. ép. de ῥαίνω.</p></section></article>\n<article id=\"entry-dgp-35888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 56 na letra ρ · nº geral 35888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ῥάττω (fut. ῥάξω, aor. ἔρραξα, perf. pas. ἔρραγμαι) 1 bater o chão com os pés, na dança 2 bater (tamborim) 3 golpear; dar pancadas em; derrubar alguém, ac.</p></section></article>\n<article id=\"entry-dgp-35889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾷστα</h1><div class=\"entry-meta\"><span>DGP · ordem 57 na letra ρ · nº geral 35889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ῥᾳδίως.</p></section></article>\n<article id=\"entry-dgp-35890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾴστος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 58 na letra ρ · nº geral 35890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de ῥᾴδιος.</p></section></article>\n<article id=\"entry-dgp-35891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳστωνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 59 na letra ρ · nº geral 35891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. entregar-se à falta de ânimo; levar uma vida indolente, descuidada; viver na inércia. 〈ῥᾳστώνη〉</p></section></article>\n<article id=\"entry-dgp-35892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥᾳστώνη,</h1><div class=\"entry-meta\"><span>DGP · ordem 60 na letra ρ · nº geral 35892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ῥῃστώνη, ης (ἡ) 1 facilidade (de trajeto, de fuga): μετὰ ῥᾳστώνης plat. com facilidade, πολλὴ ῥ. γίγνεται plat. há grande facilidade para, é muito fácil, inf. 2 facilidade de humor; boa vontade; complacência; gentileza: ἐκ ῥῃστώνης τῆς Δημοκήδεος her. por complacência a Democedes 3 comedimento; sobriedade 4 tempo de repouso, de calma; descanso 5 comodidade; bem-estar; conforto; facilidade: ὀλίγοις πόνοις πολλὰς ῥᾳστώνας κτώμενος isócr. com pouco esforço obtendo para si muitas facilidades, παρασκευάσασθαι ῥᾳστώνην τινά τῆς πόσεως plat. arranjar um meio de facilitar a bebida 6 despreocupação; indolência; moleza. 〈ῥᾴστος〉</p></section></article>\n<article id=\"entry-dgp-35893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαφανίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 61 na letra ρ · nº geral 35893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rábano; rabanete.</p></section></article>\n<article id=\"entry-dgp-35894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάφανος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 62 na letra ρ · nº geral 35894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 couve 2 rábano.</p></section></article>\n<article id=\"entry-dgp-35895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαφεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 63 na letra ρ · nº geral 35895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">maquinador; conspirador. 〈ῥάπτω〉</p></section></article>\n<article id=\"entry-dgp-35896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαφή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 64 na letra ρ · nº geral 35896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 costura 2 Anat. sutura (do crânio ou de um osso). 〈ῥάπτω〉</p></section></article>\n<article id=\"entry-dgp-35897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαφίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 65 na letra ρ · nº geral 35897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agulha 2 Zool. agulha, peixe.</p></section></article>\n<article id=\"entry-dgp-35898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαχία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 66 na letra ρ · nº geral 35898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ῥηχίη, ης (ἡ) 1 rochedo contra o qual se quebram as ondas do mar 2 litoral formado por rochedos, penhascos 3 fluxo marinho que se quebra contra as rochas 4 transbordamento (de gente, de discurso). 〈ῥήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-35899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥαχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 67 na letra ρ · nº geral 35899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἐρράχιζον) quebrar a espinha dorsal para fazer morrer; matar a pancadas, a pauladas (espec. animais). 〈ῥάχις〉</p></section></article>\n<article id=\"entry-dgp-35900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥάχις, ιος</h1><div class=\"entry-meta\"><span>DGP · ordem 68 na letra ρ · nº geral 35900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. εως (ἡ) 1 parte inferior do espinhaço; espinha dorsal 2 dorso; lombo 2 Medic. saliência da escápula 3 Bot. nervura medial (da folha) 4 cimo; cume (de montanha) 5 Zool. parte externa dos tentáculos do polvo. 〈ῥάχος〉</p></section></article>\n";
